<?php declare(strict_types=1);use PHPUnit\Framework\TestCase;
final class CorporateCreditCardPurchasesTest extends TestCase
{
 public function testRoutesUseCreditCardsCategoryAndPublicIds():void{$root=dirname(__DIR__,2);$routes=require $root.'/routes/web.php';foreach(['/corporate/credit-card-purchases','/corporate/credit-card-purchases/create','/corporate/credit-card-purchases/{purchasePublicId}','/corporate/credit-card-purchases/{purchasePublicId}/edit','/corporate/credit-card-purchases/{purchasePublicId}/receipt','/corporate/credit-card-purchases/{purchasePublicId}/receipts/{receiptPublicId}/view','/corporate/credit-card-purchases/{purchasePublicId}/receipts/{receiptPublicId}/download'] as $path){self::assertArrayHasKey($path,$routes);self::assertContains('credit-cards-access',$routes[$path]['middleware']);}self::assertStringNotContainsString('{propertyId}',(string)file_get_contents($root.'/routes/web.php'));}
 public function testControllerHasIndependentCategoryGuardAndNoPropertyAccessAuthority():void{$source=(string)file_get_contents(dirname(__DIR__,2).'/app/Http/Controllers/CorporateCreditCardPurchaseController.php');self::assertStringContainsString("canAccessCategory(\$c,'credit-cards')",$source);self::assertStringContainsString("if(!\$this->allowed(\$request))",$source);foreach(['PropertyAccessService','canAccessProperty','employee_class','admin'] as $forbidden)self::assertStringNotContainsString($forbidden,$source);self::assertStringContainsString("['Cache-Control'=>'private, no-store']",$source);}
 public function testPropertyAndEmployeeSelectorsUseAuthoritativePublicIds():void{$root=dirname(__DIR__,2);$create=(string)file_get_contents($root.'/resources/views/corporate/credit-card-purchases/create.php');foreach(['name="property_public_id"','name="purchased_by_employee_public_id"','Corporate','Managers','Assistant Managers','Maintenance','Purchase Information','Receipt Documentation'] as $required)self::assertStringContainsString($required,$create);foreach(['name="property_id"','name="submitted_by','type="hidden" name="property','<script','style='] as $forbidden)self::assertStringNotContainsString($forbidden,$create);$repo=(string)file_get_contents($root.'/app/Repositories/CreditCardPurchaseRepository.php');foreach(["status='active'","ORDER BY (property_code='CO') DESC,display_name",'public_id=?','employment_status=\'active\''] as $required)self::assertStringContainsString($required,$repo);}
 public function testCompanyListSummaryAndSharedArchitecture():void{$root=dirname(__DIR__,2);$repo=(string)file_get_contents($root.'/app/Repositories/CreditCardPurchaseRepository.php');foreach(['companyList','companySummary','COALESCE(SUM(p.amount),0.00)','submitted_by_name','property_name','p.vendor LIKE ?','p.description LIKE ?','p.card_last_four LIKE ?'] as $required)self::assertStringContainsString($required,$repo);foreach(['corporate_credit_card_purchases','FLOAT','DOUBLE'] as $forbidden)self::assertStringNotContainsString($forbidden,$repo.(string)file_get_contents($root.'/app/Services/CreditCardPurchaseService.php'));$view=(string)file_get_contents($root.'/resources/views/corporate/credit-card-purchases/index.php');foreach(['All Properties','Total Posted','Submitted By','Receipt Attached','Receipt Missing','No credit card purchases have been recorded.','No credit card purchases match these filters.'] as $required)self::assertStringContainsString($required,$view);}
 public function testCorporateQueriesAreScopedToAuthenticatedSubmitterWhileCommunityQueriesRemainPropertyScoped():void{$root=dirname(__DIR__,2);$repo=(string)file_get_contents($root.'/app/Repositories/CreditCardPurchaseRepository.php');$service=(string)file_get_contents($root.'/app/Services/CreditCardPurchaseService.php');$controller=(string)file_get_contents($root.'/app/Http/Controllers/CorporateCreditCardPurchaseController.php');foreach(['companyList(int $submitter','companySummary(int $submitter','companyWhere(int $submitter','WHERE p.submitted_by_user_id=?','public_id=? AND submitted_by_user_id=?','companyReceiptDocument(string $purchasePublic,string $receiptPublic,int $submitter)'] as $required)self::assertStringContainsString($required,$repo);self::assertStringContainsString('scopeCorporateUser($c->user->id)',$controller);self::assertStringContainsString('requiredCorporateSubmitter()',$service);self::assertStringContainsString('WHERE p.property_id=? AND p.status<>\'voided\'',$repo);self::assertStringNotContainsString('submitted_by_user_id',self::methodSource($repo,'filteredWhere','companyWhere'));$view=(string)file_get_contents($root.'/resources/views/corporate/credit-card-purchases/index.php');self::assertStringContainsString('you post',$view);self::assertStringNotContainsString('company-wide',$view);}
 public function testSharedHistoryReceiptsAndCorporatePropertyCorrection():void{$root=dirname(__DIR__,2);$service=(string)file_get_contents($root.'/app/Services/CreditCardPurchaseService.php');foreach(['submission_source','community_actions','corporate','correctCorporate','addCorporateReceipt','companyReceiptDocument','prior_property_public_id','new_property_public_id'] as $required)self::assertStringContainsString($required,$service);$show=(string)file_get_contents($root.'/resources/views/corporate/credit-card-purchases/show.php');foreach(['document-viewer.php','Credit Card Receipt','Reason for Correction','Property changed from','/corporate/credit-card-purchases/'] as $required)self::assertStringContainsString($required,$show);self::assertStringNotContainsString('Wasabi',$show);}
 public function testAllCorporatePurchasePagesUseControllerProvidedProjectRootAndRender():void{$root=dirname(__DIR__,2);$controller=(string)file_get_contents($root.'/app/Http/Controllers/CorporateCreditCardPurchaseController.php');self::assertStringContainsString('$projectRoot=dirname($this->views,2)',$controller);$views=[];foreach(['index','create','show','edit'] as $name){$source=(string)file_get_contents($root.'/resources/views/corporate/credit-card-purchases/'.$name.'.php');self::assertStringContainsString("Navigation::forRoute('/dashboard',\$projectRoot)",$source);self::assertStringNotContainsString('dirname(__DIR__,3)',$source);self::assertStringNotContainsString('resources/config/navigation.php',$source);self::assertStringNotContainsString('C:\\xampp',$source);$views[$name]=$source;}self::assertStringContainsString('Dashboard',$views['index'].$views['create'].$views['show'].$views['edit']);self::assertStringContainsString('Corporate',$views['index'].$views['create'].$views['show'].$views['edit']);foreach(['index','create','show','edit'] as $name)self::assertStringContainsString('Credit Card Purchases',$views[$name]);$working=(string)file_get_contents($root.'/resources/views/corporate/application-reviews/index.php');self::assertStringContainsString('dirname(__DIR__,4)',$working);}
 public function testIndexCreateDetailAndEditTemplatesActuallyRender():void{$root=dirname(__DIR__,2);$user=new \NpmGateway\ValueObjects\AuthenticatedUser(1,2,str_repeat('U',26),str_repeat('E',26),'tester','Test User');$projectRoot=$root;$csrfToken='csrf';$logoutCsrfToken='csrf';$navbarCorporateItems=[];$properties=[['public_id'=>str_repeat('P',26),'display_name'=>'Corporate']];$employees=[['public_id'=>str_repeat('E',26),'display_name'=>'Test Employee','role_group'=>'Corporate']];$purchase=['id'=>1,'public_id'=>str_repeat('R',26),'property_id'=>1,'property_public_id'=>str_repeat('P',26),'property_name'=>'Corporate','card_last_four'=>'0425','purchase_date'=>'2026-08-05','amount'=>'1.05','purchased_by_employee_public_id'=>str_repeat('E',26),'purchased_by_name'=>'Test Employee','vendor'=>'Vendor','description'=>'Description','submitted_by_name'=>'Test User','submitted_at'=>'2026-08-05 12:00:00','updated_at'=>'2026-08-05 12:00:00','status'=>'posted','receipt_status'=>'missing','missing_receipt_reason'=>'Unavailable receipt','history'=>[]];$render=static function(string $name,array $vars)use($root):string{extract($vars,EXTR_SKIP);ob_start();require $root.'/resources/views/corporate/credit-card-purchases/'.$name.'.php';return (string)ob_get_clean();};$common=compact('user','projectRoot','csrfToken','logoutCsrfToken','navbarCorporateItems');$index=$render('index',$common+['search'=>'','receipt'=>'','selected'=>'','properties'=>$properties,'filtersActive'=>false,'purchases'=>[],'summary'=>['total'=>0,'total_posted'=>'0.00','attached'=>0,'missing'=>0],'success'=>'']);$create=$render('create',$common+['input'=>[],'errors'=>[],'properties'=>$properties,'employees'=>$employees]);$show=$render('show',$common+['purchase'=>$purchase,'success'=>'','error'=>'']);$edit=$render('edit',$common+['purchase'=>$purchase,'input'=>['property_public_id'=>$properties[0]['public_id'],'record_version'=>str_repeat('V',26)],'errors'=>[],'properties'=>$properties,'employees'=>$employees]);foreach([$index,$create,$show,$edit] as $html){self::assertStringContainsString('gateway-navbar',$html);self::assertStringContainsString('Credit Card',$html);}}
 private static function methodSource(string $source,string $start,string $next):string{$from=strpos($source,'function '.$start);$to=strpos($source,'function '.$next,$from);return substr($source,$from,$to-$from);}
}
